83	STATIC int dcmi_get_board_type_by_config(void)
84	{
85	    char info_line[DCMI_CFG_LINE_MAX_LEN] = {0};
86	    char *tmp_str = NULL;
87	    size_t read_count;
88	    FILE *fp = NULL;
89	
90	    fp = fopen(BOARD_CONFIG_FILE, "r");
91	    if (fp == NULL) {
92	        return DCMI_ERR_CODE_FILE_OPERATE_FAIL;
93	    }
94	
95	    if (fseek(fp, 0, SEEK_SET) != 0) {
96	        gplog(LOG_ERR, "call fseek failed.");
97	        (void)fclose(fp);
98	        return DCMI_ERR_CODE_FILE_OPERATE_FAIL;
99	    }
100	
101	    read_count = fread(info_line, 1, sizeof(info_line) - 1, fp);
102	    if (read_count <= 0) {
103	        gplog(LOG_ERR, "call fread failed.read_count=%zu", read_count);
104	        (void)fclose(fp);
105	        return DCMI_ERR_CODE_FILE_OPERATE_FAIL;
106	    }
107	
108	    info_line[DCMI_CFG_LINE_MAX_LEN - 1] = '\0';
109	    tmp_str = strstr(info_line, BOARD_TYPE_KEY);
110	    if (tmp_str == NULL) {
111	        (void)fclose(fp);
112	        return DCMI_ERR_CODE_FILE_OPERATE_FAIL;
113	    }
114	
115	    // key要全字匹配
116	    if (info_line != tmp_str && *(tmp_str - 1) != '\n') {
117	        (void)fclose(fp);
118	        return DCMI_ERR_CODE_FILE_OPERATE_FAIL;
119	    }
120	
121	    // 500 A2在rc流程设置单板信息
122	    if (strncmp(tmp_str + strlen(BOARD_TYPE_KEY), "A500_A2", strlen("A500_A2")) == 0) {
123	        (void)fclose(fp);
124	        return DCMI_ERR_CODE_INNER_ERR;
125	    }
126	
127	    dcmi_set_chip_type(DCMI_CHIP_TYPE_D310);
128	    dcmi_set_board_type(DCMI_BOARD_TYPE_MODEL);
129	    dcmi_set_product_type(DCMI_A200_MODEL_3000);
130	    if (strncmp(tmp_str + strlen(BOARD_TYPE_KEY), BOARD_TYPE_HILENS, strlen(BOARD_TYPE_HILENS)) == 0) {
131	        dcmi_set_sub_board_type(DCMI_BOARD_TYPE_MODEL_HILENS);
132	    } else {
133	        dcmi_set_sub_board_type(DCMI_BOARD_TYPE_MODEL_SEI);
134	    }
135	
136	    gplog(LOG_INFO, "board_type = %d sub_board_type = %d.", dcmi_get_board_type(), dcmi_get_sub_board_type());
137	    (void)fclose(fp);
138	    return DCMI_OK;
139	}
