141	STATIC int dcmi_get_board_type_by_i2c(void)
142	{
143	#ifndef _WIN32
144	    int err;
145	    char buff[DCMI_BOARD_ID_LEN] = {0};
146	
147	    err = dcmi_i2c_get_data_9555(I2C0_DEV_NAME, I2C_SLAVE_PCA9555_BOARDINFO, 0x0, buff, sizeof(buff));
148	    if (err < 0) {
149	        gplog(LOG_ERR, "call dcmi_i2c_get_data_9555 failed. err is %d.", err);
150	        return DCMI_ERR_CODE_INNER_ERR;
151	    }
152	
153	    if (buff[0] == DCMI_310_DEVELOP_C_BOARD_ID || buff[0] == DCMI_310_DEVELOP_A_BOARD_ID) {
154	        dcmi_set_sub_board_type(DCMI_BOARD_TYPE_SOC_BASE);
155	    }
156	#endif
157	    return DCMI_OK;
158	}
