743	int dcmi_init_board_type(const int *device_logic_id, int device_count)
744	{
745	    struct dsmi_board_info_stru board_info = {0};
746	    int ret, i;
747	    unsigned int mode = 0;
748	
749	    dcmi_init_board_details_default();
750	    /* current dsmi lib for Ascend 310 Model can not get pcie info */
751	    ret = dcmi_get_board_type_by_config();
752	    if (ret == DCMI_OK) {
753	        return DCMI_OK;
754	    }
755	
756	    ret = dcmi_get_rc_ep_mode(&mode);
757	    if (ret != DCMI_OK) {
758	        gplog(LOG_ERR, "dcmi_get_rc_ep_mode failed. ret is %d", ret);
759	        return dcmi_convert_error_code(ret);
760	    }
761	
762	    for (i = 0; i < device_count; i++) {
763	        if (dcmi_get_boot_status(mode, device_logic_id[i]) != DCMI_OK) {
764	            continue;
765	        }
766	
767	        ret = dcmi_get_board_info_handle(device_logic_id[i], &board_info);
768	        if (ret == DCMI_OK) {
769	            break;
770	        }
771	    }
772	
773	    if (ret != DCMI_OK) {
774	        gplog(LOG_ERR, "dsmi_get_board_info failed. ret is %d", ret);
775	        return ret;
776	    }
777	
778	    if (mode == DCMI_PCIE_RC_MODE) {
779	        dcmi_init_chip_board_product_for_rc(device_logic_id[i], board_info.board_id);
780	        g_board_details.board_id = (int)board_info.board_id;
781	        return DCMI_OK;
782	    } else {
783	        ret = dcmi_init_chip_board_product_for_ep(device_logic_id[i], &board_info);
784	        if (ret != DCMI_OK) {
785	            gplog(LOG_ERR, "dcmi_init_chip_board_product_for_ep. ret is %d", ret);
786	            return ret;
787	        }
788	        return DCMI_OK;
789	    }
790	}
