809	STATIC void dcmi_flush_card_info_cpu_id(struct dcmi_card_info *card_info)
810	{
811	    bool board_type_supported = dcmi_board_type_is_station() ||
812	        dcmi_board_type_is_hilens() || dcmi_board_type_is_soc_develop();
813	    if (board_type_supported) {
814	        if ((card_info->mcu_id == -1) && (!dcmi_board_type_is_hilens())) {
815	            card_info->cpu_id = card_info->device_count;
816	        } else {
817	            card_info->cpu_id = card_info->device_count + 1;
818	        }
819	        if (dcmi_check_run_in_docker()) {
820	            card_info->cpu_id = -1;
821	        }
822	    } else {
823	        card_info->cpu_id = -1;
