1001	STATIC int dcmi_init_pcie_slot_info_from_dmidecode_info(FILE *p_file)
1002	{
1003	    int length, slot_id;
1004	    char msginfo[MAX_PCIE_INFO_LENTH] = {0};
1005	    char *find_flag = NULL;
1006	    char *info_start_index = NULL;
1007	    char *in_use = NULL;
1008	    struct dcmi_single_solt_pcie_map *pcie_self_info = NULL;
1009	    char *end_ptr = NULL;
1010	    int has_find = -1;
1011	
1012	    while (!feof(p_file)) {
1013	        if (fgets(&msginfo[0], MAX_PCIE_INFO_LENTH, p_file) == NULL) {
1014	            break;
1015	        }
1016	
1017	        if (in_use == NULL) {
1018	            in_use = strstr(&msginfo[0], "Current Usage: In Use");
1019	        }
1020	
1021	        if (has_find == -1) {
1022	            info_start_index = dcmi_init_dmidecode_info_slot_id_parse(msginfo);
1023	            if (info_start_index == NULL) {
1024	                continue;
1025	            }
1026	            slot_id = strtol(info_start_index, &end_ptr, DCMI_NUMBER_BASE);
1027	            has_find = 1;
1028	        } else {
1029	            find_flag = strstr(&msginfo[0], "Bus Addr: ");
1030	            if (find_flag == NULL) {
1031	                continue;
1032	            }
1033	
1034	            if (in_use == NULL) {
1035	                has_find = -1;
1036	                continue;
1037	            }
1038	
1039	            pcie_self_info = &g_pcie_map_info.single_slot_pcie_map[g_pcie_map_info.pcie_num];
1040	            pcie_self_info->slot_id = slot_id;
1041	            length = (int)strlen(find_flag);
1042	            if ((length <= 0) || (length >= MAX_PCIE_INFO_LENTH)) {
1043	                continue;
1044	            }
1045	
1046	            if (memcpy_s(&pcie_self_info->pcie_info[0], MAX_PCIE_INFO_LENTH, find_flag, length) != DCMI_OK) {
1047	                gplog(LOG_ERR, "dcmi_init_pcie_slot_info_from_dmidecode_info call memcpy_s failed");
1048	            }
1049	            pcie_self_info->pcie_info[length] = '\n';
1050	            g_pcie_map_info.pcie_num++;
1051	
1052	            has_find = -1;
1053	            in_use = NULL;
1054	        }
1055	    }
1056	    return DCMI_OK;
1057	}
