1333	int check_is_init_in_310()
1334	{
1335	    char info_line[DCMI_CFG_LINE_MAX_LEN] = {0};
1336	    char *tmp_str = NULL;
1337	    size_t read_count;
1338	    FILE *fp = NULL;
1339	 
1340	    fp = fopen(BOARD_CONFIG_FILE, "r");
1341	    if (fp == NULL) {
1342	        return DCMI_ERR_CODE_FILE_OPERATE_FAIL;
1343	    }
1344	 
1345	    if (fseek(fp, 0, SEEK_SET) != 0) {
1346	        gplog(LOG_ERR, "call fseek failed.");
1347	        (void)fclose(fp);
1348	        return DCMI_ERR_CODE_FILE_OPERATE_FAIL;
1349	    }
1350	 
1351	    read_count = fread(info_line, 1, sizeof(info_line) - 1, fp);
1352	    if (read_count <= 0) {
1353	        gplog(LOG_ERR, "call fread failed.read_count=%zu", read_count);
1354	        (void)fclose(fp);
1355	        return DCMI_ERR_CODE_FILE_OPERATE_FAIL;
1356	    }
1357	 
1358	    info_line[DCMI_CFG_LINE_MAX_LEN - 1] = '\0';
1359	    tmp_str = strstr(info_line, BOARD_TYPE_KEY);
1360	    if (tmp_str == NULL) {
1361	        (void)fclose(fp);
1362	        return DCMI_ERR_CODE_FILE_OPERATE_FAIL;
1363	    }
1364	 
1365	    // key要全字匹配
