387	bool dcmi_is_in_root_group(void)
388	{
389	    int is_root_group = 0;
390	    int ngroups = getgroups(0, NULL);
391	    gid_t *groups = NULL;
392	
393	    if (ngroups <= 0) {
394	        gplog(LOG_ERR, "get groups num failed.");
395	        return false;
396	    }
397	
398	    groups = (gid_t *)malloc(ngroups * sizeof(gid_t));
399	    if (groups == NULL) {
400	        gplog(LOG_ERR, "groups malloc failed.");
401	        return false;
402	    }
403	
404	    if (getgroups(ngroups, groups) < ngroups) {
405	        free(groups);
406	        gplog(LOG_ERR, "get groups list failed.");
407	        return false;
408	    }
409	
410	    for (int i = 0; i < ngroups; i++) {
411	        if (groups[i] == 0) {
412	            is_root_group = 1;
413	            break;
414	        }
415	    }
416	    free(groups);
417	
418	    if (is_root_group == 0) {
419	        gplog(LOG_OP, "User is not in root group.");
420	        return false;
421	    }
422	
423	    return true;
424	}

