250	    int index = 0;
251	    int ret, str_num;
252	    char *info_inner = info;
253	
254	    /* 虚拟机中最前面的为'/'字符，需要跳过 */
255	    if (info_inner[0] == '/') {
256	        info_inner = info_inner + 1;
257	    }
258	
259	    while ((str_tmp = strsep(&info_inner, "/")) != NULL) {
260	        pci_info_list[index] = (char *)malloc(MAX_PCIE_INFO_LENTH);
261	
262	        if (pci_info_list[index] == NULL) {
