268	        }
269	        index++;
270	        ret = memset_s(pci_info_list[index - 1], MAX_PCIE_INFO_LENTH, 0, MAX_PCIE_INFO_LENTH);
271	        if (ret != DCMI_OK) {
272	            gplog(LOG_ERR, "call memset_s failed.%d.", ret);
273	            for (str_num = 0; str_num < index; str_num++) {
274	                free(pci_info_list[str_num]);
275	            }
276	            return DCMI_ERR_CODE_MEM_OPERATE_FAIL;
277	        }
278	
279	        ret = strcpy_s(pci_info_list[index - 1], MAX_PCIE_INFO_LENTH, str_tmp);
280	        if (ret != DCMI_OK) {
281	            gplog(LOG_ERR, "call strcpy_s failed.%d.", ret);
282	            for (str_num = 0; str_num < index; str_num++) {
283	                free(pci_info_list[str_num]);
284	            }
285	            return DCMI_ERR_CODE_MEM_OPERATE_FAIL;
286	        }
287	    }
288	
289	    *list_len = index;
290	    return DCMI_OK;
291	}
