325	        pci_info_list[str_index - pcie_pre_index.switch_pre_index - 1]);
326	    if (ret != DCMI_OK) {
327	        gplog(LOG_ERR, "call strcpy_s failed.%d.", ret);
328	    }
329	
330	    for (str_num = 0; str_num < str_index; str_num++) {
331	        free(pci_info_list[str_num]);
