560	STATIC int dcmi_calc_card_id(struct dcmi_pcie_info_all *pcie_info, int *card_id, int is_without_switch)
561	{
562	    unsigned int domain = (unsigned int)pcie_info->domain;
563	    unsigned int bus = pcie_info->bdf_busid;
564	    unsigned int rc = pcie_info->bdf_deviceid;
565	    unsigned int func = pcie_info->bdf_funcid;
566	    unsigned int chip_num_in_one_card = (unsigned int)dcmi_get_device_count_in_one_card();
567	    if (chip_num_in_one_card == 0) {
568	        gplog(LOG_ERR, "chip_num_in_one_card is zero.");
569	        return DCMI_ERR_CODE_INNER_ERR;
570	    }
571	
572	    /* card id is named in this way */
573	    if (is_without_switch == TRUE && g_board_details.board_id == DCMI_310_CARD_DMPB_BOARD_ID) {
574	        *card_id = (domain << (unsigned int)DCMI_DOMAIN_SHIFT) + (bus << (unsigned int)DCMI_BUS_ID_SHIFT) +
575	                   ((rc / chip_num_in_one_card) << (unsigned int)DCMI_RC_ID_SHIFT) + func;
576	    } else {
577	        *card_id = (domain << (unsigned int)DCMI_DOMAIN_SHIFT) + (bus << (unsigned int)DCMI_BUS_ID_SHIFT) +
578	                   (rc << (unsigned int)DCMI_RC_ID_SHIFT) + func;
579	    }
580	
581	    return DCMI_OK;
582	}
