587	    unsigned int tran_common = 0;
588	    if (common_len >= DCMI_PCIE_ID_MIN_LEN) {
589	        gplog(LOG_ERR, "common_len exceeds buffer size. common_len: %d, buffer size: %d",
590	            common_len, DCMI_PCIE_ID_MIN_LEN - 1);
591	        return DCMI_ERR_CODE_SECURE_FUN_FAIL;
592	    }  // 防止数组访问越界
593	    int ret = memcpy_s(&common_curr[0], DCMI_PCIE_ID_MIN_LEN, bus_id_str + common_pos, common_len);
594	    if (ret != EOK) {
595	        gplog(LOG_ERR, "call memcpy_s failed.%d.", ret);
596	        return DCMI_ERR_CODE_SECURE_FUN_FAIL;
