598	    common_curr[common_len] = '\0';
599	
600	    ret = sscanf_s(common_curr, "%x", &tran_common);
601	    if (ret <= EOK) {
602	        gplog(LOG_ERR, "common_curr call sscanf_s failed.%d.", ret);
603	        return DCMI_ERR_CODE_SECURE_FUN_FAIL;
604	    }
605	    *common_num = tran_common;
606	    return DCMI_OK;
607	}
608	
609	STATIC int dcmi_trans_pcie_bus_id_without_switch(const char *bus_id_str, int *value, int is_without_switch)
610	{
611	    int ret;
612	    struct dcmi_pcie_info_all pcie_info = {0};
613	
614	    if (strlen(bus_id_str) < DCMI_PCIE_ID_MIN_LEN) {
615	        return DCMI_ERR_CODE_INVALID_PARAMETER;
616	    }
617	
618	    ret = dcmi_trans_pcie_common_id(bus_id_str, DCMI_DOMAIN_LEN, 0, (unsigned int *)&pcie_info.domain);
619	    if (ret != DCMI_OK) {
620	        gplog(LOG_ERR, "dcmi_trans_pcie_common_id failed.%d", ret);
621	        return ret;
622	    }
623	    ret = dcmi_trans_pcie_common_id(bus_id_str, DCMI_BUS_ID_LEN, DCMI_BUS_ID_POS, &pcie_info.bdf_busid);
624	    if (ret != DCMI_OK) {
625	        gplog(LOG_ERR, "dcmi_trans_pcie_common_id failed.%d", ret);
626	        return ret;
627	    }
628	    ret = dcmi_trans_pcie_common_id(bus_id_str, DCMI_RC_ID_LEN, DCMI_RC_ID_POS, &pcie_info.bdf_deviceid);
629	    if (ret != DCMI_OK) {
630	        gplog(LOG_ERR, "dcmi_trans_pcie_common_id failed.%d", ret);
631	        return ret;
632	    }
633	
634	    ret = dcmi_trans_pcie_common_id(bus_id_str, DCMI_FUNC_ID_LEN, DCMI_FUNC_ID_POS, &pcie_info.bdf_funcid);
635	    if (ret != DCMI_OK) {
636	        gplog(LOG_ERR, "dcmi_trans_pcie_common_id failed.%d", ret);
637	        return ret;
638	    }
639	
640	    return dcmi_calc_card_id(&pcie_info, value, is_without_switch);
641	}
642	
643	STATIC int dcmi_get_bus_id(const char *pcie_info_pre, int *card_id)
644	{
645	    if (dcmi_card_is_without_switch()) {
646	        return dcmi_trans_pcie_bus_id_without_switch(pcie_info_pre, card_id, TRUE);
647	    }
648	
649	    return dcmi_trans_pcie_bus_id_without_switch((const char *)pcie_info_pre, card_id, FALSE);
650	}
651	
652	STATIC void dcmi_get_bus_id_from_root_pcie_info(int device_id_logic, struct dcmi_card_pcie_info *card_pcie_info)
653	{
654	    int ret, bus_id;
655	    int card_id_curr = 0;
656	    struct dsmi_board_info_stru board_info = {0};
657	    unsigned int health = HEALTH_UNKNOWN;
658	
659	    ret = dsmi_get_device_health(device_id_logic, &health);
660	    if (ret != DSMI_OK || health == DCMI_DEVICE_NOT_EXIST) {
661	        gplog(LOG_ERR, "dsmi_get_device_health error.(logic_id=%d, health=%u, ret=%d).", device_id_logic,
662	            health, ret);
663	        return;
664	    }
665	
666	    ret = dsmi_get_board_info(device_id_logic, &board_info);
667	    if (ret != DSMI_OK) {
668	        if (ret != DSMI_ERR_RESOURCE_OCCUPIED) {
669	                gplog(LOG_ERR, "dsmi_get_board_info failed.%d. %s %d %s.", ret, "get chip", device_id_logic,
670	                    "board information failed. Reboot OS to repair if necessary");
671	            }
672	            return;
673	        }
674	
675	    ret = dcmi_get_bus_id((const char *)card_pcie_info->root_pcie_info, &bus_id);
676	    if (ret != DCMI_OK) {
677	        bus_id = (int)card_pcie_info->pcie_info_curr.bdf_busid;
678	    }
679	
680	    if (dcmi_card_is_without_switch()) {
681	        if (dcmi_get_board_chip_type() == DCMI_CHIP_TYPE_D910_93) {
682	            (void)dcmi_find_card_id_with_slot_id(&card_id_curr, board_info.slot_id);
683	        } else {
684	            (void)dcmi_find_card_id_with_bus_id(&card_id_curr, bus_id);
685	        }
686	    } else {
687	        (void)dcmi_find_card_id_with_pcie(&card_id_curr, (const char *)&card_pcie_info->root_pcie_info[0]);
688	    }
689	    dcmi_init_card_info(card_id_curr, bus_id, card_pcie_info, device_id_logic, board_info.slot_id);
690	    return;
691	}
692	
693	STATIC bool dcmi_matched_pcie_info_exist(char *msginfo, char **matched_d_chip_pcie_info, int matched_size)
694	{
695	    for (int i = 0; i < matched_size; i++) {
696	        if ((matched_d_chip_pcie_info[i] != NULL) && (strstr(msginfo, matched_d_chip_pcie_info[i]) != NULL)) {
697	            return true;
698	        }
699	    }
700	    return false;
701	}
702	
703	STATIC int dcmi_add_matched_pcie_info(char *d_chip_pcie_info, char **matched_d_chip_pcie_info, int *matched_size)
704	{
705	    int ret;
706	
707	    char *curr_pcie_info = (char *)malloc(MAX_PCIE_INFO_LENTH);
708	    if (curr_pcie_info == NULL) {
709	        gplog(LOG_ERR, "curr_pcie_info malloc failed.");
710	        return DCMI_ERR_CODE_INNER_ERR;
711	    }
712	
713	    ret = sprintf_s(curr_pcie_info, MAX_PCIE_INFO_LENTH - 1, "%s", d_chip_pcie_info);
714	    if (ret <= DCMI_OK) {
715	        gplog(LOG_ERR, "call sprintf_s failed. ret is %d", ret);
716	        free(curr_pcie_info);
717	        return DCMI_ERR_CODE_SECURE_FUN_FAIL;
718	    }
719	
720	    matched_d_chip_pcie_info[(*matched_size)] = curr_pcie_info;
721	    (*matched_size)++;
722	    return DCMI_OK;
723	}
724	
725	STATIC void dcmi_free_matched_pcie_info(char **matched_d_chip_pcie_info, int matched_size)
726	{
727	    if (matched_d_chip_pcie_info != NULL) {
728	        for (int i = 0; i < matched_size; i++) {
729	            if (matched_d_chip_pcie_info[i] != NULL) {
730	                free(matched_d_chip_pcie_info[i]);
731	                matched_d_chip_pcie_info[i] = NULL;
732	            }
733	        }
734	        free(matched_d_chip_pcie_info);
735	        matched_d_chip_pcie_info = NULL;
736	    }
737	}
738	
739	// 当前接口为static仅内部调用，card_pcie_info来源可控，不做重复检查以控制函数在50行内。后续使用需注意
740	STATIC int dcmi_get_card_id_from_bus_id(const int *device_id_list, int device_count,
741	    struct dcmi_card_pcie_info *card_pcie_info)
742	{
743	    int ret, num_id;
744	    FILE *pci_file = NULL;
745	    char msginfo[MAX_PCIE_INFO_LENTH] = {0};
746	    struct dcmi_device_id_info device_id_info = {0};
747	    char **matched_d_chip_pcie_info = (char **)malloc(device_count * sizeof(char *));
748	    int matched_size = 0;
749	
750	    if (matched_d_chip_pcie_info == NULL) {
751	        gplog(LOG_ERR, "matched_d_chip_pcie_info malloc failed.");
752	        return DCMI_ERR_CODE_INNER_ERR;
753	    }
754	
755	    ret = dcmi_save_pcie_info(&pci_file);
756	    if (ret != DCMI_OK) {
757	        gplog(LOG_ERR, "call dcmi_save_pcie_info. ret is %d", ret);
758	        free(matched_d_chip_pcie_info);
759	        return ret;
760	    }
761	#ifndef _WIN32
762	    while (!feof(pci_file)) {
763	        if (matched_size >= device_count) {
764	            gplog(LOG_INFO, "matched_size >= device_count, end reading pci_file.");
765	            break;
766	        }
767	        if ((fgets(msginfo, MAX_PCIE_INFO_LENTH, pci_file) == NULL) ||
768	            (device_id_info.find_device_num == device_count)) {
769	            break;
770	        }
771	#endif
772	        // 检查当前PCIE设备文件是否已在之前匹配过
773	        if (dcmi_matched_pcie_info_exist(msginfo, matched_d_chip_pcie_info, matched_size)) {
774	            continue;
775	        }
776	        for (num_id = 0; num_id < device_count; num_id++) {
777	            device_id_info.device_id_logic = device_id_list[num_id];
778	            ret = dcmi_get_pcie_info_inner(msginfo, MAX_PCIE_INFO_LENTH, &device_id_info, card_pcie_info);
779	            if (ret != DCMI_OK) {
780	                continue;
781	            }
782	            // 将匹配成功的PCIE设备号记入列表
783	            (void)dcmi_add_matched_pcie_info(card_pcie_info->d_chip_pcie_info, matched_d_chip_pcie_info, &matched_size);
784	            (void)dcmi_get_bus_id_from_root_pcie_info(device_id_info.device_id_logic, card_pcie_info);
785	        }
786	#ifndef _WIN32
787	    }
788	    (void)pclose(pci_file);
789	#endif
790	    dcmi_free_matched_pcie_info(matched_d_chip_pcie_info, matched_size);
791	    return DCMI_OK;
792	}
793	
794	STATIC void dcmi_get_same_split_num_from_str(char *str_info, const char *split_info, int *num)
795	{
796	    char *src_info = str_info;
797	    char *find_curr = NULL;
798	    size_t split_len = strlen(split_info);
799	    int find_num = 0;
800	
801	    while (1) {
802	        find_curr = strstr(src_info, split_info);
803	        if (find_curr == NULL) {
804	            break;
805	        }
806	        src_info = find_curr + split_len;
807	        find_num++;
808	    }
809	    *num = find_num;
810	    return;
811	}
812	
813	STATIC int dcmi_find_board_pcie_num(char *msginfo, int msginfo_len, const char *pci_curr_info, int *device_num)
814	{
815	#ifndef _WIN32
816	    char *find_flag = NULL;
817	    int split_num = 0;
818	    int device_num_curr = 0;
819	    find_flag = strstr(msginfo, pci_curr_info);
820	    if (find_flag == NULL) {
821	        return DCMI_ERR_CODE_INNER_ERR;
822	    }
823	    dcmi_get_same_split_num_from_str(find_flag, "/", &split_num);
824	    if (split_num == DCMI_SPLIT_NUM) {
825	        device_num_curr++;
826	    }
827	    *device_num = device_num_curr;
828	#else
829	    const int board_pcie_num = 2;
830	    *device_num = board_pcie_num;
831	#endif
832	    return DCMI_OK;
833	}
834	
835	STATIC void dcmi_flush_pcie_device()
836	{
837	    int ret, card_index;
838	    int device_num = 0;
839	    struct dcmi_card_info *card_info = NULL;
840	    char msginfo[MAX_PCIE_INFO_LENTH] = {0};
841	    FILE *pci_file = NULL;
842	
843	    if (dcmi_get_board_type() != DCMI_BOARD_TYPE_CARD) {
844	        return;
845	    }
846	#ifndef _WIN32
847	    ret = dcmi_save_pcie_info(&pci_file);
848	    if (ret != DCMI_OK) {
849	        gplog(LOG_ERR, "call dcmi_save_pcie_info. ret is %d", ret);
850	        return;
851	    }
852	    while (!feof(pci_file)) {
853	        if ((fgets(msginfo, MAX_PCIE_INFO_LENTH, pci_file) == NULL)) {
854	            break;
855	        }
856	#endif
857	        for (card_index = 0; card_index < g_board_details.card_count; card_index++) {
858	            card_info = &g_board_details.card_info[card_index];
859	            ret = dcmi_find_board_pcie_num(msginfo, MAX_PCIE_INFO_LENTH, &card_info->pcie_info_pre[0], &device_num);
860	            if ((ret == 0) && (device_num > card_info->device_count)) {
861	                card_info->device_loss = device_num - card_info->device_count;
862	            } else if (ret == DCMI_ERR_CODE_INNER_ERR) {
863	                continue;
864	            } else {
865	                card_info->device_loss = 0;
866	            }
867	        }
868	#ifndef _WIN32
869	    }
870	    (void)pclose(pci_file);
871	#endif
872	    return;
873	}
874	
875	int dcmi_init_for_card(const int *device_id_list, int device_count)
876	{
877	    int ret;
878	    struct dcmi_card_pcie_info card_pcie_info = { { 0 } };
879	    g_board_details.device_count = device_count;
880	    ret = dcmi_get_card_id_from_bus_id(device_id_list, device_count, &card_pcie_info);
881	    if (ret != DCMI_OK) {
882	        gplog(LOG_ERR, "dcmi_get_card_id_from_bus_id failed. ret is %d", ret);
883	        return ret;
884	    }
885	    dcmi_flush_pcie_device();
886	    g_board_details.is_has_mcu = !(dcmi_board_chip_type_is_ascend_310p_200i_pro() ||
887	        (dcmi_board_chip_type_is_ascend_950()) ||
888	        (dcmi_board_chip_type_is_ascend_310() && !dcmi_is_in_phy_machine()));
889	    g_board_details.is_has_npu = TRUE;
890	    g_board_details.mcu_access_chan = DCMI_MCU_ACCESS_BY_NPU;
891	    return DCMI_OK;
892	}

